def _fit_size(source: tuple[int, int], boundary: tuple[int, int]) -> tuple[int, int]:
    width, height = source
    max_width, max_height = boundary
    scale = min(max_width / width, max_height / height)
    return max(1, round(width * scale)), max(1, round(height * scale))


