    return {
        "status": "PASS" if passed else "FAIL",
        "real_git_lane": REAL_GIT_LANE,
        "real_git_source_count": len(by_lane[REAL_GIT_LANE]),
        "fixture_lane_count": len(CANONICAL_LANE_IDS) - 1,
