def _derive_input_kind(
    visible_input: str,
    *,
    prior_same_turn_input: bool,
) -> tuple[str, str]:
    """Derive prompt/steer/Goal from native input plus sealed turn state."""

    if _goal_context_marker_present(visible_input):
