@contextmanager
def connect(
    path: str | Path,
    *,
    readonly: bool = False,
) -> Iterator[sqlite3.Connection]:
    database_path = Path(path).resolve()
    if readonly:
        connection = sqlite3.connect(
            f"file:{database_path.as_posix()}?mode=ro&immutable=1",
            uri=True,
            timeout=30,
        )
    else:
        database_path.parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(database_path, timeout=30)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 30000")
    if readonly:
        connection.execute("PRAGMA query_only = ON")
    else:
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA synchronous = FULL")
    try:
        with connection:
            yield connection
    finally:
        connection.close()


@contextmanager
def transaction(connection: sqlite3.Connection) -> Iterator[sqlite3.Connection]:
    try:
        connection.execute("BEGIN IMMEDIATE")
        yield connection
        connection.commit()
    except Exception:
        connection.rollback()
        raise


def initialize(
    path: str | Path, *, extra_metadata: dict[str, str] | None = None
) -> None:
    schema = (
        files("evidence_lane_plugin").joinpath("schema.sql").read_text(encoding="utf-8")
    )
    with connect(path) as connection:
        connection.executescript(schema)
        metadata = {
            "engine_name": ENGINE_NAME,
            "engine_version": ENGINE_VERSION,
            "schema_version": SCHEMA_VERSION,
        }
        metadata.update(extra_metadata or {})
        connection.executemany(
            "INSERT OR REPLACE INTO metadata(key, value) VALUES (?, ?)",
            sorted(metadata.items()),
        )
        connection.commit()

def compare_source_indexes(
    prior_database: Path | None,
    current_database: Path,
) -> dict[str, Any]:
    prior = _db_file_index(prior_database) if prior_database else {}
    current = _db_file_index(current_database)
    added = [
        {"path": path, **current[path]}
        for path in sorted(current.keys() - prior.keys())
    ]
    deleted = [
        {"path": path, **prior[path]} for path in sorted(prior.keys() - current.keys())
    ]
    modified = [
        {
            "path": path,
            "before_sha256": prior[path]["sha256"],
            "after_sha256": current[path]["sha256"],
            "before_bytes": prior[path]["size_bytes"],
            "after_bytes": current[path]["size_bytes"],
            "code_family": current[path]["code_family"],
        }
        for path in sorted(prior.keys() & current.keys())
        if prior[path]["sha256"] != current[path]["sha256"]
    ]
    unchanged = sum(
        1
        for path in prior.keys() & current.keys()
        if prior[path]["sha256"] == current[path]["sha256"]
    )
    payload = {
        "added": added,
        "modified": modified,
        "deleted": deleted,
        "unchanged": unchanged,
    }
    payload["delta_sha256"] = sha256_bytes(canonical_json_bytes(payload))
    return payload

def source_tree_hash(package_root: str | Path) -> str:
    root = Path(package_root).resolve()
    members = []
    for path in sorted(root.rglob("*"), key=lambda item: item.as_posix()):
        if path.is_file() and "__pycache__" not in path.parts and path.suffix != ".pyc":
            members.append(
                {
                    "path": path.relative_to(root).as_posix(),
                    "size": path.stat().st_size,
                    "sha256": sha256_file(path),
                }
            )
    return sha256_bytes(canonical_json_bytes(members))


def toolchain_manifest() -> dict[str, Any]:
    packages = []
    for name in ("cryptography", "httpx", "mcp", "pytest"):
        try:
            package_version = version(name)
        except PackageNotFoundError:
            continue
        packages.append({"name": name, "version": package_version})
    return {
        "python": __import__("platform").python_version(),
        "implementation": __import__("platform").python_implementation(),
        "platform": __import__("platform").platform(),
        "sqlite": sqlite3.sqlite_version,
        "packages": packages,
    }


def _run_git(
    git_executable: str,
    repository_root: Path,
    arguments: list[str],
) -> subprocess.CompletedProcess[str]:
    return subprocess.run(  # nosec B603
        [git_executable, "-C", str(repository_root), *arguments],
        check=False,
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        close_fds=True,
        creationflags=(
            getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
        ),
    )


def _direct_git_commit(git_executable: str, repository_root: Path) -> str | None:
    completed = _run_git(git_executable, repository_root, ["rev-parse", "HEAD"])
    candidate = completed.stdout.strip().lower()
    if completed.returncode == 0 and _COMMIT_RE.fullmatch(candidate):
        return candidate
    return None

