            "exact_counts_preserved": True,
        }

"""Canonical JSON, hashing, and atomic file helpers."""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
from pathlib import Path
from typing import Any


def canonical_json_bytes(value: Any) -> bytes:
    return (
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
        + "\n"
    ).encode("utf-8")


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()


def sha256_file(path: str | Path, *, block_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        while block := handle.read(block_size):
            digest.update(block)
    return digest.hexdigest().upper()


def atomic_write_bytes(path: str | Path, data: bytes) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{target.name}.", suffix=".tmp", dir=target.parent
    )
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_name, target)
    finally:
        if os.path.exists(tmp_name):
            os.unlink(tmp_name)


def atomic_write_json(path: str | Path, value: Any) -> None:
    atomic_write_bytes(path, canonical_json_bytes(value))


def hash_directory_members(
    root: str | Path, names: list[str] | tuple[str, ...]
) -> dict[str, str]:
    base = Path(root)
    return {name: sha256_file(base / name) for name in sorted(names)}

"""ULID-compatible identifiers without a runtime dependency."""

from __future__ import annotations

import os
import time

_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"


def _encode_crockford(value: int, length: int) -> str:
    chars = ["0"] * length
    for index in range(length - 1, -1, -1):
        chars[index] = _ALPHABET[value & 31]
        value >>= 5
    return "".join(chars)


def new_ulid() -> str:
    timestamp_ms = int(time.time_ns() // 1_000_000) & ((1 << 48) - 1)
    randomness = int.from_bytes(os.urandom(10), "big")
    return _encode_crockford((timestamp_ms << 80) | randomness, 26)


def prefixed_id(prefix: str) -> str:
    clean = "".join(
        character
        for character in prefix.lower()
        if character.isalnum() or character == "_"
    )
    return f"{clean}_{new_ulid().lower()}"

def _candidate_source_files(root: Path) -> tuple[str, list[tuple[str, Path]]]:
    """Prefer the governed Git index; fall back only for non-Git source roots."""

    try:
        completed = subprocess.run(  # nosec B603
            ["git", "ls-files", "-z", "--cached", "--", "."],
            cwd=root,
            stdin=subprocess.DEVNULL,
            capture_output=True,
            check=False,
            timeout=60,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        completed = None
    if completed is not None and completed.returncode == 0:
        tracked: list[tuple[str, Path]] = []
        for raw in completed.stdout.split(b"\x00"):
            if not raw:
                continue
            relative = raw.decode("utf-8", errors="surrogateescape").replace("\\", "/")
            target = root / Path(relative)
            if target.is_file() and not target.is_symlink():
                tracked.append((relative, target))
        return "GIT_TRACKED_ONLY", sorted(tracked, key=lambda row: row[0].lower())

    fallback: list[tuple[str, Path]] = []
    for target in sorted(root.rglob("*"), key=lambda path: path.as_posix().lower()):
        if not target.is_file() or target.is_symlink():
            continue
        fallback.append((target.relative_to(root).as_posix(), target))
    return "FILESYSTEM_GOVERNED", fallback

def governed_source_files(
    root: str | Path,
) -> tuple[str, list[tuple[str, Path]], list[dict[str, str]]]:
    """Return safe source files plus secret-free exclusion receipts."""

    base = Path(root).resolve()
    selection, candidates = _candidate_source_files(base)
    included: list[tuple[str, Path]] = []
    excluded: list[dict[str, str]] = []
    for relative, target in candidates:
        reason = path_exclusion_reason(relative)
        if reason is None:
            try:
                reason = content_exclusion_reason(target.read_bytes())
            except OSError:
                reason = "SOURCE_FILE_UNREADABLE"
        if reason is not None:
            excluded.append(
                {"status": "EXCLUDED", "code": reason, "path": relative}
            )
            continue
        included.append((relative, target))
    return selection, included, excluded


def iter_source_files(root: str | Path) -> Iterable[tuple[str, Path]]:
    _, included, _ = governed_source_files(root)
    yield from included


def _decode(data: bytes) -> tuple[str | None, str | None]:
    if not data:
        return "", "utf-8"
    if b"\x00" in data[:8192]:
        for encoding in ("utf-16", "utf-16-le", "utf-16-be"):
            try:
                text = data.decode(encoding)
                printable = sum(
                    character.isprintable() or character.isspace() for character in text
                )
                if text and printable / len(text) > 0.85:
                    return text, encoding
            except UnicodeError:
                pass
        return None, None
    for encoding in ("utf-8-sig", "utf-8", "cp1252"):
        try:
            return data.decode(encoding), encoding
        except UnicodeError:
            continue
    return None, None


