def _line_chunks(
    text: str,
    *,
    lines_per_chunk: int,
    overlap: int,
) -> Iterable[tuple[int, int, int, str]]:
    lines = text.splitlines(keepends=True)
    if not lines:
        return
    start = 0
    ordinal = 0
    step = lines_per_chunk - overlap
    while start < len(lines):
        end = min(len(lines), start + lines_per_chunk)
        yield ordinal, start + 1, end, "".join(lines[start:end])
        if end == len(lines):
            break
        start += step
        ordinal += 1


def _python_facts(text: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    symbols: list[dict[str, Any]] = []
    imports: list[dict[str, Any]] = []
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return symbols, imports

    class Visitor(ast.NodeVisitor):
        def __init__(self) -> None:
            self.scope: list[str] = []

        def _symbol(
            self, node: ast.AST, kind: str, name: str, signature: str | None
        ) -> None:
            qualified = ".

".join([*self.scope, name])
            symbols.append(
                {
                    "kind": kind,
                    "name": name,
                    "qualified_name": qualified,
                    "start_line": getattr(node, "lineno", 1),
                    "end_line": getattr(node, "end_lineno", getattr(node, "lineno", 1)),
                    "signature": signature,
                    "parser": "python-ast",
                }
            )

        def visit_ClassDef(self, node: ast.ClassDef) -> None:
            self._symbol(node, "class", node.name, None)
            self.scope.append(node.name)
            self.generic_visit(node)
            self.scope.pop()

        def _visit_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
            args = [argument.arg for argument in node.args.args]
            self._symbol(
                node,
                "async_function"
                if isinstance(node, ast.AsyncFunctionDef)
                else "function",
                node.name,
                f"{node.name}({', '.join(args)})",
            )
            self.scope.append(node.name)
            self.generic_visit(node)
            self.scope.pop()

        visit_FunctionDef = _visit_function
        visit_AsyncFunctionDef = _visit_function

        def visit_Import(self, node: ast.Import) -> None:
            for alias in node.names:
                imports.append(
                    {
                        "module": alias.name,
                        "imported_name": None,
                        "alias": alias.asname,
                        "line_number": node.lineno,
                        "parser": "python-ast",
                    }
                )

        def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
            module = "." * node.level + (node.module or "")
            for alias in node.names:
                imports.append(
                    {
                        "module": module,
                        "imported_name": alias.name,
                        "alias": alias.asname,
                        "line_number": node.lineno,
                        "parser": "python-ast",
                    }
                )

    Visitor().visit(tree)
    return symbols, imports

def _script_facts(text: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    symbols = []
    for match in _JS_SYMBOL_RE.finditer(text):
        line = text.count("\n", 0, match.start()) + 1
        if match.group(1):
            kind, name, arguments = "class", match.group(2), None
        elif match.group(3):
            kind, name, arguments = "function", match.group(3), match.group(4)
        else:
            kind, name, arguments = "function", match.group(5), match.group(6)
        symbols.append(
            {
                "kind": kind,
                "name": name,
                "qualified_name": name,
                "start_line": line,
                "end_line": line,
                "signature": f"{name}({arguments or ''})"
                if arguments is not None
                else None,
                "parser": "script-regex",
            }
        )
    imports = [
        {
            "module": match.group(1),
            "imported_name": None,
            "alias": None,
            "line_number": text.count("\n", 0, match.start()) + 1,
            "parser": "script-regex",
        }
        for match in _JS_IMPORT_RE.finditer(text)
    ]
    return symbols, imports


def _route_facts(text: str, family: str) -> list[dict[str, Any]]:
