def transition(
    current: SessionState,
    event: LifecycleEvent,
    target: SessionState,
) -> SessionState:
    allowed = TRANSITION_LAW[event]
    require(
        (current, target) in allowed,
        "SESSION_TRANSITION_NOT_ALLOWED",
        "The requested lifecycle transition is not present in the canonical law.",
        status="BLOCKED",
        current=current.value,
        event=event.value,
        target=target.value,
        allowed=[
            {"from": source.value, "to": destination.value}
            for source, destination in sorted(
                allowed, key=lambda pair: (pair[0].value, pair[1].value)
            )
        ],
    )
    return target

def transition_catalog() -> dict[str, Any]:
    return {
        "schema": "evidence-lane.session-transition-law.v1",
        "single_authority": True,
        "events": {
            event.value: [
                {"from": source.value, "to": target.value}
                for source, target in sorted(
                    pairs, key=lambda pair: (pair[0].value, pair[1].value)
                )
            ]
            for event, pairs in TRANSITION_LAW.items()
        },
    }

def require_unfinished_execution_profile(
    profile: dict[str, str],
    *,
    host_kind: str,
) -> None:
    """Fail closed when a Codex handoff cannot prove the selector profile."""

    if not host_kind.startswith("CODEX"):
        return
    missing = [field for field in _CODEX_REQUIRED_PROFILE_FIELDS if not profile.get(field)]
    require(
        not missing,
        "STATE_TRAVEL_EXECUTION_PROFILE_INCOMPLETE",
        "Unfinished Codex State Travel requires model, submodel, reasoning effort, "
        "and reasoning speed so the destination can verify the same host profile.",
        status="BLOCKED",
        missing=missing,
        host_settings_mutation_supported=False,
    )


def execution_profile_mismatches(
    expected: dict[str, str],
    actual: dict[str, str],
) -> dict[str, dict[str, str | None]]:
    return {
        field: {"expected": value, "actual": actual.get(field)}
        for field, value in expected.items()
        if actual.get(field) != value
    }


