    *, subject: str, node_id: str, claimed: int, actual: int | None, basis: str
) -> dict[str, Any]:
    agrees = actual is not None and claimed == actual
    return {
        "subject": subject,
        "node_id": node_id,
        "claimed": claimed,
        "actual": actual,
        "basis": basis,
        "status": "PASS" if agrees else "FAIL",
    }


